"use client";
import ToursListing from "@/components/listing/tours-listing";
import Breadcrumb from "../header/breadcrumb";

export default function Page({ params }: { params: any }) {
  const initialFilterData = {
    service_types: [],
    accommodations: [],
    guiding: [],
    languages: [],
    duration: [],
    promotion_type: "discount_all",
    departureDate: "",
    lodging: [],
    activities: [],
    start: "",
    end: "",
    start_location: "",
    end_location: "",
    order: "sales",
    order_dir: "desc",
  };

  return (
    <main>
      <div className="tw-mx-auto tw-w-full tw-max-w-[1320px] tw-px-3 tw-mt-6 tw-mb-3">
        <Breadcrumb items={[{ pageTitle: "Deals", pageUrl: `/deals` }]} />
        <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-2">
          Best Tour Deals
        </h1>
        <p className="tw-mt-2 tw-text-[15px] tw-leading-relaxed tw-text-[#5d556c] tw-font-display tw-m-0">
          Save big on curated tours to the world&apos;s most iconic destinations
          — limited-time offers, unlimited memories.
        </p>
      </div>

      <ToursListing
        params={{ cities: params.cities, pageUrl: "deals" }}
        initialFilterData={initialFilterData}
        withAggregations
        showQuickFilters
      />
    </main>
  );
}
